const red={color:params.color,roughness:0.5,metalness:0.3},dk={color:'#4a4a4e',roughness:0.9},wh={color:'#e8e2d4',roughness:0.7};
const T=22,DT=8;
// deck
api.add(api.box(10.4,0.9,107).translate(0,DT-0.45,0),dk);
api.add(api.box(0.8,1.4,107).translate(-5.6,DT-0.5,0),red);api.add(api.box(0.8,1.4,107).translate(5.6,DT-0.5,0),red);
api.add(api.box(0.12,0.01,107).translate(0,DT+0.01,0),wh);
for(const sx of [-1,1])api.add(api.box(0.1,1.0,107).translate(sx*5.3,DT+0.5,0),wh);
// ramp
const rise=0.57,rl=12.1,rp=-Math.atan2(rise,12)*180/Math.PI;
api.add(api.box(10.4,0.6,rl).rotate(rp,0,0).translate(0,DT-rise/2-0.3,-53.5-6),dk);
// piers + towers
for(const tz of [-T,T]){
 for(const sx of [-1,1]){api.add(api.box(1.3,DT+34,2.2).translate(sx*5.9,(DT+34)/2,tz),red);}
 api.add(api.box(11.2,1.3,1.6).translate(0,DT+13,tz),red);api.add(api.box(11.2,1.3,1.6).translate(0,DT+25,tz),red);api.add(api.box(12,1.8,2.0).translate(0,DT+33.5,tz),red);
 api.add(api.box(11.5,DT,3.4).translate(0,DT/2-0.0,tz),{color:'#8a8478',roughness:0.95});
}
// cables
const cy=z=>{const a=Math.abs(z);return a<=T?DT+4+30*(z/T)*(z/T):DT+34-(a-T)/(53.5-T)*(34-2.5);};
const pts=[];for(let z=-53.5;z<=53.6;z+=(Math.abs(z)<T?2.75:3.1)){pts.push([0,cy(z),z]);}
for(const sx of [-1,1]){api.add(api.tube(pts.map(p=>[sx*5.9,p[1],p[2]]),0.16,6),red);
 for(let z=-19.8;z<=19.9;z+=2.2){const y=cy(z);api.add(api.box(0.07,y-DT-0.2,0.07).translate(sx*5.9,(y+DT+0.2)/2,z),{color:'#b8b2a4',roughness:0.5,metalness:0.6});}
 for(let z=-50;z<=50;z+=5.5){if(Math.abs(z)>T+1){const y=cy(z);api.add(api.box(0.06,y-DT-0.2,0.06).translate(sx*5.9,(y+DT+0.2)/2,z),{color:'#b8b2a4',roughness:0.5,metalness:0.6});}}}
api.collider({kind:'box',halfExtents:[5.2,0.45,53.5],offset:[0,DT-0.45,0]});
api.collider({kind:'box',halfExtents:[5.2,0.3,6.05],offset:[0,DT-rise/2-0.3,-59.5],rotation:[rp,0,0]});
for(const tz of [-T,T])for(const sx of [-1,1])api.collider({kind:'box',halfExtents:[0.65,(DT+34)/2,1.1],offset:[sx*5.9,(DT+34)/2,tz]});
api.add(api.box(0.2,0.1,0.2).translate(0,0.05,-66),{color:'#444444'});api.add(api.box(0.2,0.1,0.2).translate(0,0.05,66),{color:'#444444'});
return api.build();

lisbon-row.source:
const L=params.length,d=params.depth,f=params.foundation,r=()=>api.rng();
const gaps=[params.gap1,params.gap2,params.gap3,params.gap4].filter(g=>g>-900).map(g=>[g-params.gapW/2,g+params.gapW/2]);
if(params.plazaC>-900)gaps.push([params.plazaC-params.plazaW/2,params.plazaC+params.plazaW/2]);
const pal=['#e8c27a','#d98f7a','#efe3c8','#9fc0cf','#e6a95f','#c8d3a2','#f0d9d0','#d9a0a0','#f4efe0','#b9cfa8','#e7d27d','#c9a77c','#cbd9dc'];
const doors=['#3d5a45','#5a3a24','#2f4a6b','#7a2f2a'];
const trim={color:'#f6f1e6',roughness:0.8};
const dark={color:'#2b3640',roughness:0.3,metalness:0.1};
const lit={color:'#ffd08a',emissive:'#ffb860',emissiveIntensity:1.2,roughness:0.4};
const iron={color:'#25282c',roughness:0.6,metalness:0.4};
const roofs=['#b5532f','#a4452a','#c1623a'];
let x=0;
const hw=L/2;
let guard=0;
while(x<L&&guard++<400){
 const w=4.8+r()*2.4;
 let skip=false;
 for(const g of gaps){ if(x<g[1]&&x+w>g[0]){x=g[1];skip=true;break;} }
 if(skip)continue;
 if(x+w>L)break;
 const nfl=params.floorsMin+Math.floor(r()*(params.floorsMax-params.floorsMin+1));
 const h=3.5+(nfl-1)*3.05;
 const cx=x+w/2-hw;
 const col=pal[Math.floor(r()*pal.length)];
 const wm={color:col,roughness:0.92};
 api.add(api.box(w,h+f,d).translate(cx,(h-f)/2,0),wm);
 api.collider({kind:'box',halfExtents:[w/2,(h+f)/2,d/2],offset:[cx,(h-f)/2,0]});
 const zf=d/2;
 // ground floor
 const ds=r()<0.5?-1:1;
 api.add(api.box(1.15,2.35,0.16).translate(cx+ds*w*0.26,1.18,zf+0.02),trim);
 api.add(api.box(0.95,2.2,0.2).translate(cx+ds*w*0.26,1.1,zf+0.05),{color:doors[Math.floor(r()*4)],roughness:0.6});
 api.add(api.box(1.3,1.5,0.14).translate(cx-ds*w*0.24,1.7,zf+0.03),trim);
 api.add(api.box(1.1,1.3,0.18).translate(cx-ds*w*0.24,1.7,zf+0.05),r()<0.5?lit:dark);
 for(let i=1;i<nfl;i++){
  const yb=3.5+(i-1)*3.05;
  const nw=Math.max(2,Math.round(w/2.3));
  const bal=r()<0.35;
  for(let k=0;k<nw;k++){
   const wx=cx-w/2+w*(k+0.5)/nw;
   api.add(api.box(1.0,1.65,0.14).translate(wx,yb+1.45,zf+0.03),trim);
   api.add(api.box(0.8,1.45,0.18).translate(wx,yb+1.45,zf+0.05),r()<0.4?lit:dark);
  }
  if(bal){
   api.add(api.box(w*0.8,0.1,0.55).translate(cx,yb+0.55,zf+0.27),trim);
   api.add(api.box(w*0.8,0.05,0.05).translate(cx,yb+1.5,zf+0.5),iron);
   api.add(api.box(w*0.8,0.05,0.05).translate(cx,yb+1.0,zf+0.5),iron);
  }
 }
 api.add(api.box(w+0.12,0.3,0.45).translate(cx,h-0.1,zf+0.12),trim);
 const rise=0.9+r()*0.6,ang=Math.atan(rise/(d/2))*180/Math.PI,len=Math.sqrt((d/2+0.3)*(d/2+0.3)+rise*rise);
 const rm={color:roofs[Math.floor(r()*3)],roughness:0.85};
 api.add(api.box(w+0.1,0.14,len).rotate(ang,0,0).translate(cx,h+rise/2+0.05,d/4+0.1),rm);
 api.add(api.box(w+0.1,0.14,len).rotate(-ang,0,0).translate(cx,h+rise/2+0.05,-d/4-0.1),rm);
 api.add(api.extrude([[-d/2,0],[d/2,0],[0,rise]],w-0.05).rotate(0,90,0).translate(cx,h,0),wm);
 if(r()<0.35)api.add(api.box(0.55,1.4,0.55).translate(cx+(r()-0.5)*w*0.5,h+rise+0.3,-d/4),{color:'#d8cdb8',roughness:0.9});
 x+=w;
}
api.add(api.box(0.1,0.1,0.1).translate(-hw,-f+0.05,0),wm0());
api.add(api.box(0.1,0.1,0.1).translate(hw,-f+0.05,0),wm0());
function wm0(){return {color:'#8a8478',roughness:1};}
return api.build();

lisbon-terrain3.source:
const ss=(a,b,x)=>{let t=Math.min(1,Math.max(0,(x-a)/(b-a)));return t*t*(3-2*t);};
const lv=[39.6,33.1,26.6,20.1,13.6,7.1,0.6],zb=[5,26,47,68,89,110];
const st=[[-34,50],[-60,30],[-28,62],[-74,44],[-46,70],[-64,24]];
function H(x,z){
 const ax=Math.abs(x);
 let b=lv[0];
 for(let i=0;i<6;i++)b+=(lv[i+1]-lv[i])*ss(zb[i]-1,zb[i]+1,z);
 if(ax<100&&z>-10&&z<140){
  for(let i=0;i<6;i++){
   if(z<zb[i]-7.5||z>zb[i]+7.5)continue;
   for(const sx of st[i]){
    const w=1-ss(1.6,2.6,Math.abs(x-sx));
    if(w>0){const t=(z-(zb[i]-7.5))/15;const ry=lv[i]+(lv[i+1]-lv[i])*t;b=b*(1-w)+ry*w;}
   }
  }
 }
 let land=b;
 land+=30*ss(0,1,(-75-z)/130);
 const hr=55*ss(0,1,(ax-115)/150)+0.06*Math.max(0,ax-265);
 const nw=ss(0,1,(ax-120)/60);
 land+=hr;
 if(z>134)land+=40*ss(0,1,(z-300)/130);
 if(nw>0)land+=nw*(7*api.fbm2(x*0.012,z*0.012,3)+2*api.fbm2(x*0.05,z*0.05,2));
 if(z>134){
  const m=ss(0,1,(175-ax)/12)*ss(0,1,(320-z)/20)*ss(0,1,(z-134)/3);
  return land*(1-m)-3*m;
 }
 return land;
}
const P=params.part;
let m;
if(P===0){
 const zc=37.5;
 m=api.plane(300,225,200,150).displace((x,y,z)=>Math.max(-3,H(x,z+zc)));
 m.vertexColor((x,y,z)=>{
  const wz=z+zc;
  if(y<-1.5)return '#4d5f58';
  if(y<0.4&&wz>120)return '#c9bda2';
  if(Math.abs(x)<112&&wz<135&&wz>-10)return '#b0a086';
  return api.mix('#6d8b43','#8f9a52',0.5+0.5*api.noise2(x*0.05,wz*0.05));
 });
}else{
 const zc=200;
 m=api.plane(1600,1100,160,110).displace((x,y,z)=>{
  const wz=z+zc;
  const h=H(x,wz);
  const f=ss(0,1,(150-Math.abs(x))/20)*ss(0,1,(wz+75)/20)*ss(0,1,(150-wz)/20);
  return Math.max(-3.2,h-0.6-3*f);
 });
 m.vertexColor((x,y,z)=>{
  if(y<-1.5)return '#4d5f58';
  const hh=api.noise2(x*0.01,z*0.01);
  return y>45?api.mix('#8a8372','#a39d8c',0.5+0.5*hh):api.mix('#6a8741','#8a9650',0.5+0.5*hh);
 });
}
api.add(m,{roughness:0.95,metalness:0});
api.autoColliders("trimesh");
return api.build();

lisbon-street.source:
const L=params.length,W=params.width;
const m=api.plane(L,W,Math.round(L/0.25),Math.round(W/0.25));
m.vertexColor((x,y,z)=>{
 const i=Math.floor(x/0.5),j=Math.floor(z/0.5);
 const n=api.noise2(i*7.3,j*5.1);
 const az=Math.abs(z);
 if(az>W/2-0.9){
  const dk=((i+Math.floor(j/2))%5===0);
  return dk?'#6e6a66':api.mix('#d9d2c2','#c8bfae',0.5+0.5*n);
 }
 if(az>W/2-1.05)return '#9a948a';
 return api.mix('#8a857e','#a8a298',0.5+0.5*n);
});
api.add(m,{roughness:0.95,metalness:0});
if(params.rails){
 const rz=params.railZ;
 for(const s of [-0.72,0.72])api.add(api.box(L,0.08,0.07).translate(0,0.06,rz+s),{color:'#7a7e84',roughness:0.4,metalness:0.8});
 for(let x=-L/2+1;x<L/2;x+=1.3)api.add(api.box(0.2,0.04,1.9).translate(x,0.03,rz),{color:'#4a3b30',roughness:0.9});
}
return api.build();

lisbon-stairs.source:
const R=params.rise,Z=params.run,W=params.width;
const n=Math.round(R/0.2);
const sm={color:'#c7bfae',roughness:0.9};
const sm2={color:'#b3aa98',roughness:0.9};
for(let i=0;i<n;i++){
 const top=R*(1-(i+0.5)/n)+0.03;
 const h=top+0.3;
 api.add(api.box(W,h,Z/n+0.01).translate(0,(top-0.3)/2,(i+0.5)*Z/n),i%2?sm:sm2);
}
const len=Math.sqrt(Z*Z+R*R),ang=Math.atan(R/Z)*180/Math.PI;
for(const s of [-1,1])api.add(api.box(0.3,0.9,len).rotate(ang,0,0).translate(s*(W/2+0.2),R/2+0.35,Z/2),{color:'#e7dfcd',roughness:0.9});
api.collider({kind:'box',halfExtents:[0.01,0.01,0.01],offset:[0,0,0]});
return api.build();

red-bridge3.source:
const red={color:params.color,roughness:0.55,metalness:0.3};
const grey={color:'#7d8186',roughness:0.8};
const dk={color:'#3a3d42',roughness:0.9};
const E=186,T=90,DY=28,TOP=68,Wd=11;
api.add(api.box(2*E,0.8,Wd).translate(0,DY-0.4,0),dk);
api.collider({kind:'box',halfExtents:[E,0.4,Wd/2],offset:[0,DY-0.4,0]});
for(const s of [-1,1]){
 api.add(api.box(2*E,2.4,0.4).translate(0,DY-1.2,s*(Wd/2-0.2)),red);
 api.add(api.box(2*E,0.15,0.15).translate(0,DY+1.1,s*(Wd/2-0.1)),grey);
 api.add(api.box(2*E,0.15,0.15).translate(0,DY+0.55,s*(Wd/2-0.1)),grey);
}
for(let x=-E+3;x<E;x+=6){ for(const s of [-1,1])api.add(api.box(0.2,2.2,0.2).translate(x,DY-1.2,s*(Wd/2-0.2)).rotate(0,0,0),red); }
for(const tx of [-T,T]){
 for(const s of [-1,1]){
  api.add(api.box(3.2,TOP,2.4).translate(tx,TOP/2,s*5.6),red);
  api.collider({kind:'box',halfExtents:[1.6,TOP/2,1.2],offset:[tx,TOP/2,s*5.6]});
 }
 for(const y of [DY+14,DY+28,TOP-1.5])api.add(api.box(2.6,2.2,13).translate(tx,y,0),red);
}
function cab(s){
 const pts=[];
 for(let x=-E;x<=E;x+=6){
  let y;const ax=Math.abs(x);
  if(ax<=T){const u=x/T;y=DY+4+(TOP-1-(DY+4))*u*u;}
  else{const u=(ax-T)/(E-T);y=(TOP-1)-(TOP-1-(DY+2))*Math.pow(u,1.7);}
  pts.push([x,y,s*5.6]);
 }
 api.add(api.tube(pts,0.45,6),red);
 for(let x=-E+6;x<E;x+=6){
  const p=pts[Math.round((x+E)/6)];
  const h=p[1]-(DY+0.3);
  if(h>1)api.add(api.box(0.12,h,0.12).translate(x,DY+0.3+h/2,s*5.6),grey);
 }
}
cab(-1);cab(1);
return api.build();

lisbon-row3.source:
const R=()=>api.rng();
const D=params.depth, hd=D/2, base=2.0;
const M={
 plaster:{finish:'plaster',preset:'concrete',color:'#ffffff',roughness:0.95},
 stone:{finish:'limestone',preset:'stone',color:'#ffffff',roughness:0.9},
 tile:{finish:'roof-tile',preset:'brick',color:'#ffffff',roughness:0.85},
 glass:{finish:'facade',preset:'glass',color:'#16222c',opacity:0.88,roughness:0.05},
 lit:{color:'#3a2a1a',emissive:'#ffb55e',emissiveIntensity:1.4,roughness:0.4},
 wood:{finish:'paint',preset:'wood',color:'#ffffff',roughness:0.7},
 iron:{finish:'paint',preset:'metal',color:'#ffffff',metalness:0.5,roughness:0.55},
 cloth:{preset:'fabric',color:'#ffffff',roughness:0.9},
 azul:{finish:'paint',preset:'stone',color:'#ffffff',roughness:0.22}
};
const pick=a=>a[Math.floor(R()*a.length)];
function B(k,w,h,d,x,y,z,c){const m=api.box(w,h,d).translate(x,y,z);m.vertexColor(()=>c);api.add(m,M[k]);return m;}
const plast=['#e9c98c','#dc9d70','#e8b9a3','#f1e3b8','#c9d6c8','#b9cdd8','#efe7d8','#d8a66e','#d3a3a2','#a9c3b2','#f3f0e8','#e2b57f','#e6c0a0'];
const trim=['#f6f1e6','#efe6d0','#ffffff'];
const shut=['#3f6b57','#8a3b2f','#2f5f8a','#5b4a3a','#2f4f46'];
const roofc=['#f2a077','#ef9468','#e8a27c','#f4b088','#e58f66'];
const tilec=['#9fbdd0','#a8c4a0','#ebd48e','#c8d8e0','#b8c8e0'];
const doorc=['#2f4f46','#6b2a24','#27405f','#3b2f26','#1f1f22'];
const iron='#27332c';
const fmin=params.floorsMin, fmax=Math.max(params.floorsMin,params.floorsMax);
const blocks=[];
for(const g of [params.gap1,params.gap2]) if(g>-900) blocks.push([g-88-params.gapW/2,g-88+params.gapW/2]);
if(params.plazaC>-900) blocks.push([params.plazaC-88-params.plazaW/2,params.plazaC-88+params.plazaW/2]);
blocks.sort((a,b)=>a[0]-b[0]);
const free=[];let cur=-88;
for(const b of blocks){ if(b[0]>cur+4) free.push([cur,Math.min(b[0],88)]); cur=Math.max(cur,b[1]); }
if(cur<88-4) free.push([cur,88]);
const houses=[];
for(const f of free){let x=f[0];while(x<f[1]-0.01){let w=5.2+R()*3.6;if(f[1]-x-w<4.6)w=f[1]-x;if(w>10.5)w=(f[1]-x)/2;houses.push([x,w]);x+=w;}}
for(const h of houses){
 const x0=h[0],w=h[1],xc=x0+w/2;
 const n=fmin+Math.floor(R()*(fmax-fmin+1));
 const gf=3.3,fh=3.1;
 const H=base+gf+(n-1)*fh+0.25;
 const pc=pick(plast), tc=pick(trim), azu=R()<0.18;
 const zf=hd;
 B('plaster',w,H,D,xc,H/2,0,pc);
 B('stone',w+0.02,1.0,0.07,xc,base+0.5,zf+0.03,'#d8d0bc');
 B('stone',w+0.1,0.22,D+0.7,xc,H-0.11,0,tc);
 if(azu){const ac=pick(tilec);B('azul',w-0.2,H-base-1.0-0.3,0.05,xc,(base+1.0+H-0.3)/2,zf+0.03,ac);
  for(let k=1;k<n;k++)B('stone',w-0.2,0.08,0.07,xc,base+gf+(k-1)*fh+0.02,zf+0.04,'#f2efe6');}
 const hz=hd+0.33, rise=hz*0.38;
 const rf=api.extrude([[-hz,0],[hz,0],[0,rise]],w-0.04).rotate(0,90,0).translate(xc,H,0);
 const rc=pick(roofc);rf.vertexColor(()=>rc);api.add(rf,M.tile);
 if(R()<0.6){B('plaster',0.5,1.3,0.5,xc+(R()-0.5)*(w-2),H+rise*0.5+0.6,-1.0,pc);}
 if(R()<0.5)B('iron',0.1,H-base-0.3,0.1,x0+w-0.18,(H+base)/2,zf+0.1,iron);
 const nw=Math.max(2,Math.floor(w/2.4)), sp=w/nw, door=Math.floor(R()*nw);
 const sh=R()<0.75?pick(shut):null;
 const lw=()=>R()<0.25?'lit':'glass';
 function win(cx,yb,ww,hh,balc){
  B('wood',ww+0.14,hh+0.14,0.06,cx,yb+hh/2,zf+0.03,'#f6f2ea');
  B(lw(),ww,hh,0.05,cx,yb+hh/2,zf+0.06,'#ffffff');
  B('wood',0.05,hh,0.06,cx,yb+hh/2,zf+0.09,'#f6f2ea');
  B('wood',ww,0.05,0.06,cx,yb+hh*0.62,zf+0.09,'#f6f2ea');
  B('stone',ww+0.3,0.07,0.2,cx,yb-0.04,zf+0.1,'#e8e2d2');
  if(sh){B('wood',0.5,hh,0.04,cx-ww/2-0.32,yb+hh/2,zf+0.03,sh);B('wood',0.5,hh,0.04,cx+ww/2+0.32,yb+hh/2,zf+0.03,sh);}
  if(balc){const bw=ww+0.5;B('stone',bw,0.12,0.6,cx,yb-0.1,zf+0.3,'#d8d0bc');B('iron',bw,0.04,0.04,cx,yb+0.95,zf+0.58,iron);B('iron',bw,0.04,0.04,cx,yb+0.25,zf+0.58,iron);
   for(let p=0;p<=6;p++)B('iron',0.025,0.95,0.025,cx-bw/2+0.02+p*(bw-0.04)/6,yb+0.5,zf+0.58,iron);
   B('iron',0.04,0.95,0.6,cx-bw/2+0.02,yb+0.5,zf+0.3,iron);B('iron',0.04,0.95,0.6,cx+bw/2-0.02,yb+0.5,zf+0.3,iron);}
 }
 for(let i=0;i<nw;i++){
  const cx=x0+(i+0.5)*sp;
  if(i===door){const dc=pick(doorc);B('stone',1.3,2.6,0.1,cx,base+0.1+1.3,zf+0.04,'#e4ddcb');B('wood',0.98,2.35,0.08,cx,base+0.1+1.175,zf+0.09,dc);B('glass',0.6,0.5,0.03,cx,base+2.1,zf+0.14,'#ffffff');B('stone',1.5,0.08,0.5,cx,base+0.06,zf+0.28,'#cfc8b6');
   if(R()<0.35){B('cloth',1.7,0.05,0.9,cx,base+2.9,zf+0.42,pick(['#b83a2e','#2f6f8f','#d79a2b','#3f6b57']));}}
  else win(cx,base+0.85,1.0,1.4,false);
  for(let k=1;k<n;k++){
   const yb=base+gf+(k-1)*fh;
   if(k===1&&(R()<0.45)) win(cx,yb+0.05,0.95,2.2,true); else win(cx,yb+0.9,1.0,1.45,false);
  }
 }
 api.collider({kind:'box',halfExtents:[w/2,H/2,hd],offset:[xc,H/2,0]});
}
return api.build();

lisbon-street3.source:
const L=params.length, rh=2.5, sw=3.78, cobble=params.surface==='cobble';
const cell=0.2, cols=Math.round(L/cell), rows=Math.round(2*rh/cell);
const road=api.heightfield(cols,rows,L,2*rh,(x,z)=>0.04+(cobble?0.012*api.noise2(x*8,z*8):0.004*api.noise2(x*3,z*3)));
road.vertexColor((x,y,z)=>{
 const n=api.noise2(x*5.1,z*5.1)*0.5+api.noise2(x*0.7,z*0.7)*0.5;
 if(cobble){const t=0.5+0.5*n;return api.mix('#8a847a','#c2baa8',t);}
 let c=api.mix('#4a4b50','#62636a',0.5+0.5*n);
 if(params.rails&&Math.abs(z-params.railZ)<0.75)c=api.mix(c,'#6e6a62',0.5);
 return c;});
api.add(road,cobble?{finish:'cobble',preset:'stone',color:'#ffffff',roughness:0.92}:{finish:'asphalt',preset:'concrete',color:'#ffffff',roughness:0.88});
const slab=api.box(L,0.04,2*rh).translate(0,0.02,0);slab.vertexColor(()=>'#8a857b');api.add(slab,{finish:'asphalt',preset:'concrete',color:'#ffffff',roughness:0.95});
const lime={finish:'limestone',preset:'stone',color:'#ffffff',roughness:0.8};
for(const s of [-1,1]){
 const pw=sw-rh, zc=s*(rh+pw/2);
 const pc=Math.round(L/0.12), pr=Math.round(pw/0.12);
 const pv=api.heightfield(pc,pr,L,pw,(x,z)=>0.1+0.003*api.noise2(x*10,z*10));
 pv.vertexColor((x,y,z)=>{const w=Math.sin(x*1.3+Math.sin(z*2.4+x*0.15)*1.2);const edge=Math.abs(z)>pw/2-0.22;
  if(edge)return '#3a3a3d';return w>0.15?'#f0eadb':(w<-0.35?'#ddd6c4':'#3c3c40');});
 pv.translate(0,0,zc);api.add(pv,lime);
 const base=api.box(L,0.1,pw).translate(0,0.05,zc);base.vertexColor(()=>'#cfc8b6');api.add(base,lime);
 const kerb=api.box(L,0.12,0.18).translate(0,0.06,s*(rh+0.09));kerb.vertexColor(()=>'#a8a49c');api.add(kerb,{finish:'stone',preset:'stone',color:'#ffffff',roughness:0.85});
}
const bm={finish:'brushed-metal',preset:'metal',color:'#ffffff',metalness:0.8,roughness:0.4};
if(params.rails){
 for(const d of [-0.45,0.45]){const r=api.box(L,0.07,0.06).translate(0,0.075,params.railZ+d);r.vertexColor(()=>'#8a8782');api.add(r,bm);}
 const ng=Math.round(L/1.6);
 for(let i=0;i<ng;i++){const sl=api.box(0.16,0.04,1.5).translate(-L/2+0.8+i*1.6,0.06,params.railZ);sl.vertexColor(()=>'#5a4e40');api.add(sl,{finish:'oak',preset:'wood',color:'#ffffff',roughness:0.9});}
}
for(let i=0;i<6;i++){const x=-L/2+12+i*(L-24)/5+api.rng()*4, z=(api.rng()-0.5)*1.4+(params.rails?1.2:0);
 const m=api.cylinder(0.36,0.36,0.012,16).translate(x,0.058,z);m.vertexColor(()=>'#5a5a5c');api.add(m,bm);}
return api.build();

lisbon-stairs3.source:
const W=params.width, Lz=params.length, rise=params.rise, n=36, r=rise/n, t=Lz/n, off=0.3;
const lime={finish:'limestone',preset:'stone',color:'#ffffff',roughness:0.88};
const pi={finish:'paint',preset:'metal',color:'#ffffff',metalness:0.5,roughness:0.5};
const pts=[[-Lz/2,0],[-Lz/2,off+0.5*r]];
for(let i=0;i<n;i++){const x0=-Lz/2+i*t, x1=x0+t, y=off+(i+0.5)*r; if(i>0)pts.push([x0,y]); pts.push([x1,y]);}
pts.push([Lz/2,off+rise]);pts.push([Lz/2,0]);
const st=api.extrude(pts,W).rotate(0,90,0);
st.vertexColor((x,y,z)=>api.mix('#d9d2c0','#ece6d6',0.5+0.5*api.noise2(x*3,z*3+y*2)));
api.add(st,lime);
const lineY=z=>off+rise*(Lz/2-z)/Lz;
const wt=0.28, wh=0.5;
for(const s of [-1,1]){
 const poly=[[-Lz/2,0],[-Lz/2,off+wh],[Lz/2,off+rise+wh],[Lz/2,0]];
 const w=api.extrude(poly,wt).rotate(0,90,0).translate(s*(W/2+wt/2),0,0);
 w.vertexColor(()=>'#e2dccb');api.add(w,lime);
 const ix=s*(W/2+wt/2), top=[];
 for(let k=0;k<=8;k++){const z=Lz/2-k*Lz/8;top.push([ix,lineY(z)+1.0,z]);}
 const rl=api.tube(top,0.025,6);rl.vertexColor(()=>'#25342b');api.add(rl,pi);
 for(let k=0;k<=8;k++){const z=Lz/2-k*Lz/8;const p=api.box(0.05,0.55,0.05).translate(ix,lineY(z)+wh+0.27,z);p.vertexColor(()=>'#25342b');api.add(p,pi);}
}
return api.build();

lisbon-tram3.source:
const L=params.length, Wd=2.3;
const P=(m,mat,c)=>{m.vertexColor(()=>c);api.add(m,mat);};
const paint={finish:'paint',preset:'plastic',color:'#ffffff',roughness:0.35,metalness:0.2};
const met={finish:'brushed-metal',preset:'metal',color:'#ffffff',metalness:0.7,roughness:0.5};
const gl={preset:'glass',color:'#1b2a36',opacity:0.85,roughness:0.05};
const em={color:'#fff0c0',emissive:'#fff0c0',emissiveIntensity:3,roughness:0.3};
P(api.box(L,0.55,Wd).translate(0,0.85,0),paint,'#e3ae1f');
P(api.box(L-0.1,0.18,Wd+0.02).translate(0,1.2,0),paint,'#f2ead2');
P(api.box(L,0.12,Wd).translate(0,2.5,0),paint,'#f2ead2');
const np=8, pitch=(L-0.6)/np;
for(let i=0;i<=np;i++)P(api.box(0.12,1.15,Wd+0.02).translate(-L/2+0.3+i*pitch,1.9,0),paint,'#e3ae1f');
for(let i=0;i<np;i++)for(const s of [-1,1])P(api.box(pitch-0.14,0.95,0.05).translate(-L/2+0.3+(i+0.5)*pitch,1.95,s*(Wd/2-0.02)),gl,'#ffffff');
P(api.box(L,0.95,Wd-0.1).translate(0,1.95,0),paint,'#2a2218');
P(api.box(L-0.4,0.16,Wd-0.2).translate(0,2.62,0),paint,'#3a3d40');
P(api.box(L-0.2,0.08,0.6).translate(0,2.75,0),paint,'#d9d4c4');
for(const s of [-1,1]){
 P(api.box(0.1,1.1,1.5).translate(s*(L/2+0.01),1.95,0),gl,'#ffffff');
 for(const z of [-0.8,0.8])P(api.sphere(0.12,2).translate(s*(L/2+0.06),0.85,z),em,'#ffffff');
 P(api.box(0.12,0.12,0.5).translate(s*(L/2+0.02),2.45,0),em,'#ffe9a0');
 P(api.box(0.25,0.15,Wd-0.2).translate(s*(L/2+0.1),0.45,0),met,'#4a4a4c');
}
const pg=api.tube([[-0.9,2.8,0],[-0.1,3.5,0],[0.7,2.8,0]],0.03,6);P(pg,met,'#2e2e30');
P(api.box(0.08,0.04,1.4).translate(-0.1,3.52,0),met,'#2e2e30');
for(const bx of [-L/2+1.7,L/2-1.7]){
 P(api.box(2.0,0.2,1.1).translate(bx,0.42,0),met,'#303032');
 for(const dx of [-0.55,0.55])for(const z of [-0.45,0.45]){const w=api.cylinder(0.3,0.3,0.1,16).rotate(90,0,0).translate(bx+dx,0.3,z);P(w,met,'#3a3a3c');}
}
P(api.box(L-0.4,0.3,Wd-0.1).translate(0,0.55,0),paint,'#4a4036');
return api.build();
